export PATH="$HOME/.dotnet/tools:$PATH"
# Let me write a small C# script to properly extract errors from the binlog
mkdir -p /tmp/binlog-reader && cat > /tmp/binlog-reader/Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(error =>
{
    var project = "";
    var node = error.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            project = p.Name;
            break;
        }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.File ?? "", error.LineNumber, error.Text ?? error.ToString()));
});

// Group by project
Console.WriteLine("=== ERRORS BY PROJECT ===");
foreach (var group in errors.GroupBy(e => e.project).OrderBy(g => g.Key))
{
    Console.WriteLine($"\n--- Project: {group.Key} ---");
    foreach (var err in group)
    {
        Console.WriteLine($"  [{err.code}] {err.file}({err.line}): {err.message}");
    }
}

Console.WriteLine($"\n=== TOTAL ERRORS: {errors.Count} ===");

// Also show warnings that might be relevant
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(warning =>
{
    var project = "";
    var node = warning.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            project = p.Name;
            break;
        }
        node = node.Parent;
    }
    if (warning.Code != null && (warning.Code.StartsWith("MSB") || warning.Code.StartsWith("NU")))
        warnings.Add((project, warning.Code, warning.Text ?? warning.ToString()));
});

if (warnings.Any())
{
    Console.WriteLine("\n=== NOTABLE WARNINGS ===");
    foreach (var w in warnings)
    {
        Console.WriteLine($"  [{w.code}] ({w.project}): {w.message}");
    }
}
EOF

